/*
	red rise #WCCChallenge Eclipse 8.4.24 
	#generativeart #creativecoding #p5js

  Dear Raph and creative coding community,

	implementation inspired by this stunning picture from the wikipedia:
	https://en.wikipedia.org/wiki/Eclipse#/media/File:2008-08-01_Solar_eclipse_progression_with_timestamps.jpg

	Tried various implementations for the crescent / sichel based on two circles:
	- with beginClip()
	- with erase()
	- with beginShape() / beginContour()
	but all of them failed to make proper blur, which was always a circle.
	Finally went to calculate the crossing points of two circles and a shape consisting of two arcs (see vertexArc())

	Join the Birb's Nest Discord for friendly creative coding community
	and future challenges and contributions: https://discord.gg/S8c7qcjw2b
	WCCC-Contributions: https://openprocessing.org/curation/78544
*/

const debug = false;
const N = 25;
const mdf = 0.925;
let ox, oy, os;

function setup() {
	const minWH = max(windowWidth, windowHeight);
	createCanvas(minWH, minWH);
	describe("series of eclipse pictures by time");
	textAlign(CENTER, CENTER)
	noStroke();
	frameRate(15)
	ox = 0.5;
	oy = 0.5;
	os = 3 * minWH / N;
}

function draw() {
	// rotate whole sketch
	translate(width/2,height/2)
	rotate(sin(frameCount*0.01)*0.25+QUARTER_PI/3)
	translate(-width/2,-height/2)

	// background
	blendMode(BLEND)
	background(0, 0, 8);

	// eclipse series
	blendMode(ADD)
	const a = frameCount * 0.03;
	// t  = animation 0 = start, 0.5 = eclipse, 1 = end
	// dt = shift in animation -0.2 ... 0 ... 0.2 (slowness on 0, accellaration on edges)
	const dt = (1-abs(sin(a-HALF_PI))) * Math.sign(sin(a)) * 0.2; // (1-abs(sin(frameCount * 0.03)))*0.2
	let t = 0; // map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, 0, 1) * 1.1;
	let y = (height-os) / 2;
	// for (let y = 0; y < N; y++) {
		for (let x = 0; x < N; x++) {
			drawTile({x: x*os/3, y: y, ox, oy, os}, t+dt);
			t += 1/(N)
		}		
	// }

}

function drawTile(pos, t) {
	var ox, oy, os, sd = pos.os / 4, md = sd * mdf;
	ox = pos.x + pos.os * pos.ox;
	oy = pos.y + pos.os * pos.oy;
	os = pos.os

	// convert t(0..1) -> t(-1 ... 1)
	t = 1.05 * map(t, 0, 1, 1, -1); // sin(frameCount * 0.01);
	const et = 0.4; // edge for t to change color red -> white/cyan -> red

	const ctx = drawingContext;
	const gradient = ctx.createRadialGradient(ox, oy, sd/2, ox, oy, max(sd*abs(1-abs(t)*0.6), (os/2)*abs(t)))

	let clr = color(255, 0, 16);
	if (abs(t) < et) clr = lerpColor(clr, color("rgb(230,255,255)"), 1-(abs(t)/et))

	let mx = t * 2*sd/3;
	let my = -mx;

	push()
	ctx.shadowColor = clr;
	let blurSize = max(sd*abs(1-abs(t)*0.85), (os/2)*abs(t)); // 15;
	blurSize = pow(blurSize/5, 2)
	ctx.shadowBlur = blurSize;

	fill("#f0f0ff")
	drawCrescent(
		{x: ox, y: oy, d: sd},
		{x: ox + mx, y: oy + my, d: md}, 
		3
	);

	pop()
}

function drawCrescent(sun, moon, num = 1) {
	let iPts = intersect2Circles([sun.x, sun.y], sun.d/2, [moon.x, moon.y], moon.d/2);
	// console.log(iPts);
	push();

	if (iPts && iPts.length === 2) {
		// sun and moon overlapping
		sun.a1 = p5.Vector.sub(createVector(iPts[0].x, iPts[0].y), createVector(sun.x, sun.y)).heading();
		sun.a2 = p5.Vector.sub(createVector(iPts[1].x, iPts[1].y), createVector(sun.x, sun.y)).heading();
		moon.a1 = p5.Vector.sub(createVector(iPts[0].x, iPts[0].y), createVector(moon.x, moon.y)).heading();
		moon.a2 = p5.Vector.sub(createVector(iPts[1].x, iPts[1].y), createVector(moon.x, moon.y)).heading();

		//correction
		if (sun.a2 < sun.a1) sun.a2 += TWO_PI;
		if (moon.a2 < moon.a1) moon.a2 += TWO_PI;		

		for (let i = 0; i < num; i++) {			
			beginShape();
			vertexArc(sun.x, sun.y, sun.d, sun.a1, sun.a2);
			vertexArc(moon.x, moon.y, moon.d, moon.a2, moon.a1);
			endShape();
		}

	} else if (dist(sun.x, sun.y, moon.x, moon.y) < moon.d / 2) {
		// moon in sun
		beginShape();
		vertexArc(sun.x, sun.y, sun.d, 0, TWO_PI);
		beginContour();
		vertexArc(moon.x, moon.y, moon.d, TWO_PI, 0); // must "wind" reverse
		endContour();
		endShape();

	} else {
		// moon outside circle
		circle(sun.x, sun.y, sun.d)
	}

	pop();
}

function vertexArc(cx, cy, d, a1, a2, n = 0) {
	if (!n) n = ~~max(2, d * abs(a2 - a1) / TWO_PI);
	const r = d/2;
	const da = (a2 - a1) / n;
	var a = a1;
	for (let i = 0; i <= n; i++, a += da) {
		// const a = lerp(a1, a2, i/n); // a1 + i/n * (a2 - a1);
		const x = cos(a) * r + cx;
		var y = sin(a) * r + cy;
		vertex(x, y);
	}
}


// http://walter.bislins.ch/blog/index.asp?page=Schnittpunkte+zweier+Kreise+berechnen+%28JavaScript%29
function intersect2Circles( A, a, B, b ) {
  // A, B = [ x, y ]
  // return = [ Q1, Q2 ] or [ Q ] or [] where Q = [ x, y ]
  var AB0 = B[0] - A[0];
  var AB1 = B[1] - A[1];
  var c = Math.sqrt( AB0 * AB0 + AB1 * AB1 );
  if (c == 0) {
    // no distance between centers
    return [];
  }
  var x = (a*a + c*c - b*b) / (2*c);
  var y = a*a - x*x;
  if (y < 0) {
    // no intersection
    return [];
  }
  if (y > 0) y = Math.sqrt( y );
  // compute unit vectors ex and ey
  var ex0 = AB0 / c;
  var ex1 = AB1 / c;
  var ey0 = -ex1;
  var ey1 =  ex0;
  var Q1x = A[0] + x * ex0;
  var Q1y = A[1] + x * ex1;
  if (y == 0) {
    // one touch point
    return [ {x: Q1x, y: Q1y } ]; // return [ [ Q1x, Q1y ] ];
  } 
  // two intersections
  var Q2x = Q1x - y * ey0;
  var Q2y = Q1y - y * ey1;
  Q1x += y * ey0;
  Q1y += y * ey1;
  // return [ [ Q1x, Q1y ], [ Q2x, Q2y ] ];
	return [ { x: Q1x, y: Q1y }, { x: Q2x, y: Q2y } ];
}
